  for (const v of vals) {
    const x = toNum(v)
    if (x.k === 'e') return x
    nums.push(x.v)
  }
  switch (name) {
    case 'SUM': return fin(nums.reduce((s, x) => s + x, 0))
    case 'MIN': return num(nums.reduce((s, x) => Math.min(s, x)))
    case 'MAX': return num(nums.reduce((s, x) => Math.max(s, x)))
