const cells = new Map()
for (let i = 0; i < lines.length; i++) {
  const s = lines[i].replace(/^[ \t]+/, '')
  if (s === '' || s[0] === '#') continue
  const m = /^([^ \t]*)[ \t]*([^]*)$/.exec(s)
  const token = m[1]
  const a = parseAddr(token)
  if (!a) {
    process.stderr.write(`error: line ${i + 1}: invalid cell address ${token}\n`)
    process.exit(2)
  }
  const key = keyOf(a)
  if (cells.has(key)) {
    process.stderr.write(`error: line ${i + 1}: cell ${token.toUpperCase()} is declared twice\n`)
    process.exit(2)
  }
  cells.set(key, { addr: a, content: m[2] })
}

// ---- formula parsing ----
function tokenize(src) {
  const toks = []
  let i = 0
  while (i < src.length) {
    const c = src[i]
    if (c === ' ' || c === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(src.slice(i)))) {
      toks.push({ t: 'num', v: Number(m[0]) }); i += m[0].length; continue
    }
    if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(src.slice(i)))) {
      toks.push({ t: 'word', v: m[0] }); i += m[0].length; continue
    }
    if ((m = /^(<>|<=|>=|[<>=^*\/+\-():,])/.exec(src.slice(i)))) {
      toks.push({ t: 'op', v: m[0] }); i += m[0].length; continue
    }
    return null
  }
  return toks
}

class Fail extends Error {}

function parseFormula(src) {
  const toks = tokenize(src)
  if (!toks) return null
  let p = 0
  const peek = () => toks[p]
  const isOp = (v) => toks[p] && toks[p].t === 'op' && toks[p].v === v
  const fail = () => { throw new Fail() }

  function comparison() {
    let l = additive()
    while (peek() && peek().t === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(peek().v)) {
      const op = toks[p++].v
      l = { type: 'bin', op, l, r: additive() }
    }
    return l
  }
  function additive() {
    let l = term()
    while (isOp('+') || isOp('-')) {
      const op = toks[p++].v
      l = { type: 'bin', op, l, r: term() }
    }
    return l
  }
  function term() {
    let l = power()
    while (isOp('*') || isOp('/')) {
      const op = toks[p++].v
      l = { type: 'bin', op, l, r: power() }
    }
    return l
  }
  function power() {
    const l = unary()
    if (isOp('^')) {
      p++
      return { type: 'bin', op: '^', l, r: power() }
    }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) {
      const op = toks[p++].v
      return { type: 'un', op, e: unary() }
    }
    return primary()
  }
  function primary() {
    const t = toks[p]
    if (!t) fail()
    if (t.t === 'num') { p++; return { type: 'num', v: t.v } }
    if (t.t === 'op') {
      if (t.v === '(') {
        p++
        const e = comparison()
        if (!isOp(')')) fail()
        p++
        return { type: 'paren', e }
      }
      fail()
    }
    p++
    const next = toks[p]
    if (next && next.t === 'op' && next.v === '(') {
      p++
      const args = []
      if (isOp(')')) { p++ } else {
        for (;;) {
          args.push(comparison())
          if (isOp(',')) { p++; continue }
          if (isOp(')')) { p++; break }
          fail()
        }
      }
      return { type: 'call', name: t.v.toUpperCase(), args }
    }
    if (isOp(':')) {
      p++
      const t2 = toks[p]
      if (!t2 || t2.t !== 'word') fail()
      p++
      return { type: 'range', a: parseAddr(t.v), b: parseAddr(t2.v) }
    }
    const up = t.v.toUpperCase()
    if (up === 'TRUE') return { type: 'bool', v: true }
    if (up === 'FALSE') return { type: 'bool', v: false }
    return { type: 'ref', a: parseAddr(t.v) }
  }

  try {
    const e = comparison()
    if (p !== toks.length) return null
    return e
  } catch (e) {
    if (e instanceof Fail) return null
    throw e
  }
}

function rangeCells(r) {
  const out = []
  if (!r.a || !r.b) return out
  const c1 = Math.min(r.a.col, r.b.col), c2 = Math.max(r.a.col, r.b.col)
  const r1 = Math.min(r.a.row, r.b.row), r2 = Math.max(r.a.row, r.b.row)
  for (let c = c1; c <= c2; c++) for (let w = r1; w <= r2; w++) out.push({ col: c, row: w })
  return out
}

function analyze(e, deps) {
  let ok = true
  const go = (n, isDirect) => {
    switch (n.type) {
      case 'ref': if (n.a) deps.push(n.a); break
      case 'range':
        if (!isDirect) ok = false
        for (const c of rangeCells(n)) deps.push(c)
        break
      case 'bin': go(n.l, false); go(n.r, false); break
      case 'un': case 'paren': go(n.e, false); break
      case 'call': for (const a of n.args) go(a, true); break
    }
  }
  go(e, false)
  return ok
}

// ---- evaluation ----
const parsed = new Map()
function getParsed(key, content) {
  let r = parsed.get(key)
  if (!r) {
    const tree = parseFormula(content.slice(1))
    const deps = []
    const ok = tree ? analyze(tree, deps) : false
    r = { tree, ok, deps: tree ? deps : [] }
    parsed.set(key, r)
  }
  return r
}

const memo = new Map()
const stack = new Set()

function cellValue(a) {
  const key = keyOf(a)
  if (memo.has(key)) return memo.get(key)
  const cell = cells.get(key)
  if (!cell) return num(0)
  if (stack.has(key)) return err('#CYCLE!')
  stack.add(key)
  const v = evalContent(key, cell.content)
  stack.delete(key)
  memo.set(key, v)
  return v
}

function evalContent(key, content) {
  if (content[0] === '=') {
    const r = getParsed(key, content)
    if (!r.tree || !r.ok) return err('#ERR!')
    return ev(r.tree)
  }
  if (content === '') return num(0)
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(content)) return num(Number(content))
  if (ERRORS.includes(content)) return err(content)
  return txt(content)
}

function toNum(v) {
  if (v.k === 'e' || v.k === 'n') return v
  if (v.k === 'b') return num(v.v ? 1 : 0)
  return err('#VALUE!')
}
const fin = (x) => (Number.isFinite(x) ? num(x) : err('#DIV/0!'))

const kindRank = (v) => (v.k === 'n' ? 0 : v.k === 't' ? 1 : 2)
function compare(a, b) {
  const ra = kindRank(a), rb = kindRank(b)
  if (ra !== rb) return ra < rb ? -1 : 1
  if (a.k === 't') {
    const x = Array.from(a.v), y = Array.from(b.v)
    const n = Math.min(x.length, y.length)
    for (let i = 0; i < n; i++) {
      const cx = x[i].codePointAt(0), cy = y[i].codePointAt(0)
      if (cx !== cy) return cx < cy ? -1 : 1
    }
    return x.length === y.length ? 0 : x.length < y.length ? -1 : 1
  }
  const x = a.k === 'b' ? Number(a.v) : a.v
  const y = b.k === 'b' ? Number(b.v) : b.v
  return x < y ? -1 : x > y ? 1 : 0
}

function ev(n) {
  switch (n.type) {
    case 'num': return num(n.v)
    case 'bool': return bool(n.v)
    case 'paren': return ev(n.e)
    case 'ref': return n.a ? cellValue(n.a) : err('#REF!')
    case 'range': return err('#ERR!')
    case 'un': {
      const v = toNum(ev(n.e))
      if (v.k === 'e') return v
      return num(n.op === '-' ? -v.v : v.v)
    }
    case 'bin': {
      const l = ev(n.l)
      const r = ev(n.r)
      if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
        if (l.k === 'e') return l
        if (r.k === 'e') return r
        const c = compare(l, r)
        switch (n.op) {
          case '=': return bool(c === 0)
          case '<>': return bool(c !== 0)
          case '<': return bool(c < 0)
          case '<=': return bool(c <= 0)
          case '>': return bool(c > 0)
          default: return bool(c >= 0)
        }
      }
      const a = toNum(l)
      if (a.k === 'e') return a
      const b = toNum(r)
      if (b.k === 'e') return b
      switch (n.op) {
        case '+': return fin(a.v + b.v)
        case '-': return fin(a.v - b.v)
        case '*': return fin(a.v * b.v)
        case '/': return b.v === 0 ? err('#DIV/0!') : fin(a.v / b.v)
        default: return fin(Math.pow(a.v, b.v))
      }
    }
    case 'call': return evCall(n)
  }
}

function evCall(n) {
  const name = n.name
  if (name === 'IF') {
    if (n.args.length !== 3) return err('#ERR!')
    if (n.args.some((a) => a.type === 'range')) return err('#VALUE!')
    const c = ev(n.args[0])
    if (c.k === 'e') return c
    if (c.k === 't') return err('#VALUE!')
    const t = c.k === 'b' ? c.v : c.v !== 0
    return ev(n.args[t ? 1 : 2])
  }
  if (name === 'ABS') {
    if (n.args.length !== 1) return err('#ERR!')
    if (n.args[0].type === 'range') return err('#VALUE!')
    const v = ev(n.args[0])
    if (v.k === 'e') return v
    if (v.k === 't') return err('#VALUE!')
    return num(Math.abs(toNum(v).v))
  }
  if (!['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'].includes(name)) return err('#NAME?')
  if (n.args.length < 1) return err('#ERR!')
  const vals = []
  for (const a of n.args) {
    if (a.type === 'range') {
      if (!a.a || !a.b) { vals.push(err('#REF!')); continue }
      for (const c of rangeCells(a)) vals.push(cellValue(c))
    } else vals.push(ev(a))
  }
  const e = vals.find((v) => v.k === 'e')
  if (e) return e
  if (name === 'COUNT') return num(vals.filter((v) => v.k === 'n').length)
  const nums = []
  for (const v of vals) {
    const x = toNum(v)
    if (x.k === 'e') return x
    nums.push(x.v)
  }
  switch (name) {
    case 'SUM': return fin(nums.reduce((s, x) => s + x, 0))
    case 'MIN': return num(nums.reduce((s, x) => Math.min(s, x)))
    case 'MAX': return num(nums.reduce((s, x) => Math.max(s, x)))
    default: return fin(nums.reduce((s, x) => s + x, 0) / nums.length)
  }
}

function fmt(v) {
  switch (v.k) {
    case 'n': return String(Number(v.v.toPrecision(10)))
    case 'b': return v.v ? 'TRUE' : 'FALSE'
    default: return v.v
  }
}

const keys = [...cells.keys()].sort((a, b) => a - b)
const out = []
for (const key of keys) {
  const cell = cells.get(key)
  const name = nameOf(cell.addr)
  if (mode === 'values') {
    out.push(`${name}=${fmt(cellValue(cell.addr))}`)
  } else {
    let line = `${name}:`
    if (cell.content[0] === '=') {
      const r = getParsed(key, cell.content)
      const set = new Map()
      for (const d of r.deps) set.set(keyOf(d), d)
      for (const k of [...set.keys()].sort((a, b) => a - b)) line += ' ' + nameOf(set.get(k))
    }
    out.push(line)
  }
}
process.stdout.write(out.length ? out.join('\n') + '\n' : '')
